import fs from "node:fs";
const text = fs.readFileSync("src/project-seed.ts", "utf8");
const ids = [...text.matchAll(/id: "(project-\d{3})"/g)].map(([, id]) => id);
const titles = [...text.matchAll(/title: "(Project \d{3})"/g)].map(([, title]) => title);
const expected = Array.from({ length: 120 }, (_, i) => String(i + 1).padStart(3, "0"));
const checks = {
  ids: ids.length === 120,
  titles: titles.length === 120,
  idSequence: ids.every((id, i) => id === `project-${expected[i]}`),
  titleSequence: titles.every((title, i) => title === `Project ${expected[i]}`),
  statuses: (text.match(/status: "published"/g) ?? []).length === 120,
  size: text.length > 10000,
};
console.log(checks);
if (!Object.values(checks).every(Boolean)) process.exit(1);
console.log("semantic validation: passed");
